// ValidateAssertListenAddr validates that a string is a valid listen address (host:port format).
// Corresponds to the (consts.assert_listen_addr) annotation.
func ValidateAssertListenAddr(addr string) error {
	// Must be in host:port format
	host, portStr, err := net.SplitHostPort(addr)
	if err != nil {
		return protoerrors.NewErrMissingInvalidData(err, "invalid host:port format")
	}

	// Validate host (can be IP, hostname, or empty for any)
	if host != "" && host != "*" {
		// Try parsing as IP
		if ip := net.ParseIP(host); ip == nil {
			// Not an IP, check if it's a valid hostname
			hostnameRegex := regexp.MustCompile(`^[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)*$`)
			if !hostnameRegex.MatchString(host) {
				return protoerrors.NewErrMissingInvalidData(nil, "invalid host: must be IP address, hostname, or empty")
			}
		}
	}

	// Validate port
	port := 0
	if _, err := fmt.Sscanf(portStr, "%d", &port); err != nil || port < 0 || port > 65535 {
		return protoerrors.NewErrMissingInvalidData(nil, "invalid port: must be 0-65535, got: %s", portStr)
	}

	return nil
}

