// ValidateAssertSemver validates that a string follows semantic versioning.
// Accepts formats like "1.0.0", "v2.3.4", "1.0.0-alpha.1", "1.0.0+build.123".
// Corresponds to the (spec.assert_semver) annotation.
func ValidateAssertSemver(version string) error {
	semverRegex := regexp.MustCompile(`^v?(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$`)
	if !semverRegex.MatchString(version) {
		return protoerrors.NewErrMissingInvalidData(nil, "invalid semantic version format: %s", version)
	}
	return nil
}
